<?php
declare(strict_types=1); require dirname(__DIR__) . '/app/core/bootstrap.php'; require_role('admin'); $ticketModel=new Ticket($pdo); $userModel=new User($pdo); $status=trim((string) ($_GET['status'] ?? '')) ?: null; $priority=trim((string) ($_GET['priority'] ?? '')) ?: null; $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST' && post_text('action')==='assign'){if(!verify_csrf_token($_POST['csrf_token']??null))$errors[]='Invalid form token.'; $ticketId=filter_var($_POST['ticket_id']??null,FILTER_VALIDATE_INT); $techId=filter_var($_POST['technician_id']??null,FILTER_VALIDATE_INT); $techs=$userModel->technicians(); $validTech=array_column($techs,'id'); if(!$ticketId||!$techId||!in_array($techId,$validTech))$errors[]='Invalid ticket or technician.'; if(!$errors){$ticket=$ticketModel->find($ticketId); if(!$ticket)$errors[]='Ticket not found.'; elseif(in_array($ticket['status'],['resolved','closed'],true))$errors[]='Resolved or closed tickets cannot be assigned.'; else{$ticketModel->assign($ticketId,$techId,(int)current_user()['id']);flash('message','Technician assigned.');redirect('admin_tickets.php');}}}
$tickets=$ticketModel->all($status,$priority); $technicians=$userModel->technicians(); require dirname(__DIR__).'/app/views/layout.php'; page_header('Manage tickets'); ?><div class="toolbar"><h1>Manage tickets</h1></div><?php if($message=flash('message')):?><p class="message"><?=e($message)?></p><?php endif;?><?php foreach($errors as $error):?><p class="error"><?=e($error)?></p><?php endforeach;?><form class="panel grid" method="get"><p><label>Status</label><select name="status"><option value="">All</option><?php foreach(Ticket::statuses() as $value):?><option <?= $status===$value?'selected':''?>><?=e($value)?></option><?php endforeach;?></select></p><p><label>Priority</label><select name="priority"><option value="">All</option><?php foreach(Ticket::priorities() as $value):?><option <?= $priority===$value?'selected':''?>><?=e($value)?></option><?php endforeach;?></select></p><p><button type="submit">Filter</button></p></form><div class="panel"><table><tr><th>Title</th><th>Requester</th><th>Status</th><th>Priority</th><th>Assignment</th></tr><?php foreach($tickets as $ticket):?><tr><td><a href="ticket.php?id=<?= (int)$ticket['id'] ?>"><?=e($ticket['title'])?></a></td><td><?=e($ticket['requester'])?></td><td><?=e($ticket['status'])?></td><td><?=e($ticket['priority'])?></td><td><?php if(in_array($ticket['status'],['resolved','closed'],true)): ?><?=e($ticket['technician_name']??'Not assigned')?><?php else: ?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="assign"><input type="hidden" name="ticket_id" value="<?= (int)$ticket['id'] ?>"><select name="technician_id" required><option value="">Select</option><?php foreach($technicians as $tech):?><option value="<?= (int)$tech['id'] ?>" <?= (int)$ticket['technician_id']===(int)$tech['id']?'selected':''?>><?=e($tech['first_name'].' '.$tech['last_name'])?></option><?php endforeach;?></select><button type="submit">Assign</button></form><?php endif; ?></td></tr><?php endforeach;?></table></div><?php page_footer(); ?>